/**
 * Produces `server.mjs` — a single self-contained file that any MCP client can
 * run with plain Node, from any folder, with no install and no network.
 *
 * The "bundler" is intentionally tiny: the runtime modules are dependency-free
 * by design, so inlining them means dropping relative imports and the `export`
 * keywords. Node's own builtins stay imported as-is.
 */

import { readFileSync } from 'node:fs';

const RUNTIME_MODULES = ['./util.js', './tokenizer.js', './search.js', './mcp-runtime.js'];

/**
 * @param {string} source
 * @returns {string}
 */
function inlineModule(source) {
  return source
    .split('\n')
    .filter((line) => !/^\s*import\s.*from\s*['"]\.\//.test(line))
    .join('\n')
    .replace(/^export\s+/gm, '')
    .replace(/\/\*\*[\s\S]*?\*\//g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * @param {{name?: string, version?: string}} [options]
 * @returns {string}
 */
export function bundleServer(options = {}) {
  const name = options.name || 'hanmcp';
  const version = options.version || '0.1.0';

  const bodies = RUNTIME_MODULES.map((relative) =>
    inlineModule(readFileSync(new URL(relative, import.meta.url), 'utf8')),
  );

  const banner = [
    '#!/usr/bin/env node',
    '//',
    `// ${name} - documentation MCP server, generated by hanmcp.`,
    '// Self-contained and dependency-free. Point any MCP client at this file.',
    '//',
    "import { fileURLToPath } from 'node:url';",
  ].join('\n');

  const footer = [
    '',
    "const HANMCP_DIR = fileURLToPath(new URL('.', import.meta.url));",
    `createServer({ dir: HANMCP_DIR, name: ${JSON.stringify(name)}, version: ${JSON.stringify(version)} }).start();`,
    '',
  ].join('\n');

  return `${banner}\n\n${bodies.join('\n\n')}\n${footer}`;
}
